// Minimal argparse-compatible argument parsing for:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
import { basename } from 'node:path';

const OPTIONS = ['--help', '--a', '--b'];

function prog() {
  const argv1 = process.argv[1];
  return argv1 ? basename(argv1) : '';
}

function usage() {
  return `usage: ${prog()} [-h] --a A --b B`;
}

function printHelp() {
  process.stdout.write(
    usage() +
      '\n\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n' +
      '  --b B\n'
  );
}

function fail(message) {
  process.stderr.write(usage() + '\n' + prog() + ': error: ' + message + '\n');
  process.exit(2);
}

// Resolve a long option (possibly an unambiguous prefix) to its full name,
// or null if unrecognized. Exits with an argparse-style error if ambiguous.
function resolveLong(name) {
  if (OPTIONS.includes(name)) return name;
  const matches = OPTIONS.filter((opt) => opt.startsWith(name));
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) {
    fail(`ambiguous option: ${name} could match ${matches.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv /* array like process.argv.slice(2) */) {
  const result = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h') {
      printHelp();
      process.exit(0);
    }

    if (token.startsWith('--')) {
      let name = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      const resolved = resolveLong(name);
      if (resolved === '--help') {
        printHelp();
        process.exit(0);
      }
      if (resolved === '--a' || resolved === '--b') {
        const key = resolved.slice(2);
        if (inlineValue !== null) {
          result[key] = inlineValue;
        } else {
          const next = argv[i + 1];
          // argparse: an option-like next token means the value is missing.
          if (next === undefined || (next.startsWith('-') && next !== '-')) {
            fail(`argument ${resolved}: expected one argument`);
          }
          result[key] = next;
          i++;
        }
        continue;
      }
      // Unrecognized -- option.
      extras.push(token);
      continue;
    }

    // Bare positional / short option: unrecognized.
    extras.push(token);
  }

  const missing = [];
  if (!('a' in result)) missing.push('--a');
  if (!('b' in result)) missing.push('--b');
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: result.a, b: result.b };
}

