// Base58 (Bitcoin alphabet) encode/decode on plain arrays of byte numbers.
// Reimplementation of Python's `base58` package: b58encode / b58decode.
//
// b58encode takes a number[] of bytes and returns a number[] of ASCII char
// codes of the base58 string. Leading 0x00 bytes become leading '1' chars.
// b58decode takes a base58 string and returns a number[] of bytes; leading
// '1' chars become leading 0x00 bytes.

export const BASE58_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const ALPHABET_INDEX = new Map();
for (let i = 0; i < BASE58_ALPHABET.length; i++) {
  ALPHABET_INDEX.set(BASE58_ALPHABET[i], i);
}

export function b58encode(bytes) {
  // Count leading zero bytes.
  let zeros = 0;
  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;

  // Convert the remaining base-256 digits to base-58 digits (big-endian).
  const digits = [];
  for (let i = zeros; i < bytes.length; i++) {
    let carry = bytes[i];
    for (let j = 0; j < digits.length; j++) {
      carry += digits[j] << 8;
      digits[j] = carry % 58;
      carry = (carry / 58) | 0;
    }
    while (carry > 0) {
      digits.push(carry % 58);
      carry = (carry / 58) | 0;
    }
  }

  // digits is little-endian base-58; emit leading '1's then reversed digits.
  const out = [];
  for (let i = 0; i < zeros; i++) out.push(49); // '1'
  for (let i = digits.length - 1; i >= 0; i--) {
    out.push(BASE58_ALPHABET.charCodeAt(digits[i]));
  }
  return out;
}

export function b58decode(str) {
  // Count leading '1' characters.
  let ones = 0;
  while (ones < str.length && str[ones] === '1') ones++;

  // Convert the remaining base-58 digits to base-256 bytes (big-endian).
  const digits = [];
  for (let i = ones; i < str.length; i++) {
    const ch = str[i];
    const value = ALPHABET_INDEX.get(ch);
    if (value === undefined) {
      const err = new Error(`Invalid character '${ch}'`);
      err.name = 'ValueError';
      throw err;
    }
    let carry = value;
    for (let j = 0; j < digits.length; j++) {
      carry += digits[j] * 58;
      digits[j] = carry & 0xff;
      carry >>= 8;
    }
    while (carry > 0) {
      digits.push(carry & 0xff);
      carry >>= 8;
    }
  }

  // digits is little-endian base-256; emit leading zero bytes then reversed.
  const out = [];
  for (let i = 0; i < ones; i++) out.push(0);
  for (let i = digits.length - 1; i >= 0; i--) out.push(digits[i]);
  return out;
}

