// Exact replica of Python's repr() for a bytes object, given a plain array
// of byte numbers (0-255).
//
// Quote selection: single quotes, unless the data contains a single quote
// but no double quote, in which case double quotes are used. Backslash, the
// active quote char, \t, \n and \r are escaped; printable ASCII 0x20-0x7E
// is printed literally; everything else becomes \xNN with lowercase hex.

export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) {
      out += '\\\\';
    } else if (b === quote.charCodeAt(0)) {
      out += '\\' + quote;
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

