node --input-type=module -e "
import { utf8Encode } from '/output/lib/utf8.mjs';
import { b58encode, b58decode } from '/output/lib/base58.mjs';
import { bytesRepr } from '/output/lib/pyrepr.mjs';

const s = (codes) => codes.map(c => String.fromCharCode(c)).join('');
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const assert = (cond, msg) => { if (!cond) throw new Error('FAIL: ' + msg); };

assert(s(b58encode(utf8Encode('a'))) === '2g', 'encode a');
assert(eq(b58decode('2g'), [97]), 'decode 2g');
assert(eq(b58decode('111'), [0,0,0]), 'decode 111');
assert(s(b58encode(utf8Encode('Hello World!'))) === '2NEpo7TZRRrLZSi2U', 'encode Hello World!');
assert(eq(b58decode('2NEpo7TZRRrLZSi2U'), utf8Encode('Hello World!')), 'decode Hello World!');
assert(s(b58encode(utf8Encode('中国汉字'))) === '5KLbY4YtwK7rEVHY2', 'encode 中国汉字');
assert(eq(b58encode([]), []), 'encode empty');
assert(eq(b58decode(''), []), 'decode empty');

// round-trip with leading zeros
const data = [0,0,5,255,0,128];
assert(eq(b58decode(s(b58encode(data))), data), 'round-trip zeros');

// invalid char error
try { b58decode('0'); throw new Error('no throw'); }
catch (e) { assert(e.message === \"Invalid character '0'\" && e.name === 'ValueError', 'error shape'); }

// pyrepr
assert(bytesRepr([97]) === \"b'a'\", 'repr a');
assert(bytesRepr([0,0,0]) === \"b'\\\\x00\\\\x00\\\\x00'\", 'repr zeros');
assert(bytesRepr([]) === \"b''\", 'repr empty');
assert(bytesRepr([39]) === 'b\"\\'\"', 'repr single quote -> double quotes');
assert(bytesRepr([39,34]) === 'b\\'\\'\"\\'', 'repr both quotes');
assert(bytesRepr([92,9,10,13,126,31,128,255]) === \"b'\\\\\\\\\\\\t\\\\n\\\\r~\\\\x1f\\\\x80\\\\xff'\", 'repr escapes');

// utf8 edge cases vs Python semantics
assert(eq(utf8Encode('é'), [0xc3,0xa9]), 'utf8 e-acute');
assert(eq(utf8Encode('𐍈'), [0xf0,0x90,0x8d,0x88]), 'utf8 U+10348');
assert(eq(utf8Encode('😀'), [0xf0,0x9f,0x98,0x80]), 'utf8 emoji');
assert(eq(utf8Encode(''), []), 'utf8 empty');

console.log('ALL_TESTS_PASSED');
"

