1	// Base58 (Bitcoin alphabet) encode/decode on plain arrays of byte numbers.
2	// Reimplementation of Python's `base58` package: b58encode / b58decode.
3	//
4	// b58encode takes a number[] of bytes and returns a number[] of ASCII char
5	// codes of the base58 string. Leading 0x00 bytes become leading '1' chars.
6	// b58decode takes a base58 string and returns a number[] of bytes; leading
7	// '1' chars become leading 0x00 bytes.
8	
9	export const BASE58_ALPHABET =
10	  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
11	
12	const ALPHABET_INDEX = new Map();
13	for (let i = 0; i < BASE58_ALPHABET.length; i++) {
14	  ALPHABET_INDEX.set(BASE58_ALPHABET[i], i);
15	}
16	
17	export function b58encode(bytes) {
18	  // Count leading zero bytes.
19	  let zeros = 0;
20	  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;
21	
22	  // Convert the remaining base-256 digits to base-58 digits (big-endian).
23	  const digits = [];
24	  for (let i = zeros; i < bytes.length; i++) {
25	    let carry = bytes[i];
26	    for (let j = 0; j < digits.length; j++) {
27	      carry += digits[j] << 8;
28	      digits[j] = carry % 58;
29	      carry = (carry / 58) | 0;
30	    }
31	    while (carry > 0) {
32	      digits.push(carry % 58);
33	      carry = (carry / 58) | 0;
34	    }
35	  }
36	
37	  // digits is little-endian base-58; emit leading '1's then reversed digits.
38	  const out = [];
39	  for (let i = 0; i < zeros; i++) out.push(49); // '1'
40	  for (let i = digits.length - 1; i >= 0; i--) {
41	    out.push(BASE58_ALPHABET.charCodeAt(digits[i]));
42	  }
43	  return out;
44	}
45	
46	export function b58decode(str) {
47	  // Count leading '1' characters.
48	  let ones = 0;
49	  while (ones < str.length && str[ones] === '1') ones++;
50	
51	  // Convert the remaining base-58 digits to base-256 bytes (big-endian).
52	  const digits = [];
53	  for (let i = ones; i < str.length; i++) {
54	    const ch = str[i];
55	    const value = ALPHABET_INDEX.get(ch);
56	    if (value === undefined) {
57	      const err = new Error(`Invalid character '${ch}'`);
58	      err.name = 'ValueError';
59	      throw err;
60	    }
61	    let carry = value;
62	    for (let j = 0; j < digits.length; j++) {
63	      carry += digits[j] * 58;
64	      digits[j] = carry & 0xff;
65	      carry >>= 8;
66	    }
67	    while (carry > 0) {
68	      digits.push(carry & 0xff);
69	      carry >>= 8;
70	    }
71	  }
72	
73	  // digits is little-endian base-256; emit leading zero bytes then reversed.
74	  const out = [];
75	  for (let i = 0; i < ones; i++) out.push(0);
76	  for (let i = digits.length - 1; i >= 0; i--) out.push(digits[i]);
